/**
 * Deterministically pick one commentary entry for a course: same course
 * + same score band always shows the same note (stable across reloads),
 * but different courses/score levels see different entries from the pool.
 */
export function pickCommentary(
  category: Category,
  pct: number,
  seed: string
): CommentaryEntry | null {
  const pool = COMMENTARY.filter(
    (c) => c.category === category && pct >= c.minScore && pct < c.maxScore
  );
  if (pool.length === 0) return null;

  let hash = 0;
  for (let i = 0; i < seed.length; i++) {
    hash = (hash * 31 + seed.charCodeAt(i)) >>> 0;
  }
  return pool[hash % pool.length];
}
